// # Method: a polymorphic subject through a `@property` hop binds the
// # stored object, so the capture's write reaches `self.k.a`.
// def poly_prop_method(self) -> None:
//     match self.kennel.a:  # tpyc: ok
//         case Hound():
//             print("poly-prop-method hound")
//         case Animal() as a:
//             a.legs = 6
//     print("poly-prop-method", self.k.a.legs)
inline void Pen::poly_prop_method() {
    auto& __match_subject_1 = this->kennel().a;
    if (Hound* __mpoly_0 = dynamic_cast<Hound*>(&__match_subject_1)) {
        Hound& __case_0 = *__mpoly_0;
        std::cout << "poly-prop-method hound" << "\n" << ::tpy::check_signals;
    } else if (Animal* __mpoly_1 = dynamic_cast<Animal*>(&__match_subject_1)) {
        Animal& __case_1 = *__mpoly_1;
        auto& a = __case_1;
        a.legs = 6;
    }
    std::cout << "poly-prop-method" << " " << this->k.a.legs << "\n" << ::tpy::check_signals;
}

// # Method: a reference result over a durable argument binds the
// # element itself.
// def first_method(self, c: Bag) -> None:
//     match first(c):  # tpyc: ok
//         case Item() as it:
//             it.n = 21
//     print("record-call-method", c.items[0].n)
inline void Pen::first_method(Bag& c) const {
    Item* it;
    auto& __match_subject_1 = ::tpyapp::main::first(c);
    {
        it = &(__match_subject_1);
        it->n = 21;
    }
    std::cout << "record-call-method" << " " << ::tpy::__getitem__(c.items, 0).n << "\n" << ::tpy::check_signals;
}

