struct Tree {
    using variant_type = ::tpy::Union<int32_t, std::vector<Tree>>;
    variant_type value;

    Tree() = default;
    template<typename T>
        requires std::constructible_from<variant_type, T&&>
    Tree(T&& v) : value(std::forward<T>(v)) {}

    bool operator==(const Tree&) const = default;

    std::string __str__() const {
        return ::tpy::__str__(static_cast<const typename variant_type::base_variant&>(value));
    }
    std::string __repr__() const {
        return ::tpy::__repr__(static_cast<const typename variant_type::base_variant&>(value));
    }

    friend std::ostream& operator<<(std::ostream& os, const Tree& v) {
        return os << v.__str__();
    }
};
struct V {
    using variant_type = ::tpy::Union<std::monostate, int32_t, std::vector<V>>;
    variant_type value;

    V() = default;
    template<typename T>
        requires std::constructible_from<variant_type, T&&>
    V(T&& v) : value(std::forward<T>(v)) {}

    bool operator==(const V&) const = default;

    std::string __str__() const {
        return ::tpy::__str__(static_cast<const typename variant_type::base_variant&>(value));
    }
    std::string __repr__() const {
        return ::tpy::__repr__(static_cast<const typename variant_type::base_variant&>(value));
    }

    friend std::ostream& operator<<(std::ostream& os, const V& v) {
        return os << v.__str__();
    }
};


